p='/app/runs/bottle_preclose2';m=json.load(open(p+'/meta.json'));T=np.array(m['cameras']['robot0_eye_in_hand']['cam2world_gl']);K=np.array(m['cameras']['robot0_eye_in_hand']['intrinsic_cv']);d=np.load(p+'/depth_robot0_eye_in_hand.npy')[-1].astype(float);print('cam',T[:3,3], 'eef',m['proprio']['now'][26:29]);
for x,y in [(160,140),(170,145),(180,155),(140,125),(125,112),(208,165)]:
